SOUL_GROUP = {}
for _, s in ipairs(TS2_SOULS) do SOUL_GROUP[s.code] = s.group end
local function on(code) return (Tracker:ProviderCountForCode(code) or 0) > 0 end
function souls_group_on(g) return on("set_souls_" .. g) end
-- $soul|<code>: the soul is in, or its group isn't being played
function soul(code)
  local g = SOUL_GROUP[code]
  if g and not souls_group_on(g) then return 1 end
  return on(code) and 1 or 0
end
-- The Final Showdown fight's souls (Require Final Showdown Soul(s): all three
-- with Miniboss Souls on, Stinky Pete's alone with only Boss Souls; and
-- Woody / Jessie per the goal setting). Not needed to ENTER the level.
function fs_souls_needed()
  local need = {}
  if on("set_souls_fs") then
    if souls_group_on("miniboss") then
      need = { "soul_stinky_pete", "soul_gunslinger", "soul_blacksmith" }
    elseif souls_group_on("boss") then
      need = { "soul_stinky_pete" }
    end
  end
  local o = Tracker:FindObjectForCode("set_souls_wj_off")
  local wj = (o and o.CurrentStage) or 0
  if wj == 1 or wj == 3 then need[#need + 1] = "soul_woody" end
  if wj == 2 or wj == 3 then need[#need + 1] = "soul_jessie" end
  return need
end
function fs_souls()
  for _, c in ipairs(fs_souls_needed()) do if not on(c) then return 0 end end
  return 1
end

-- ── room on the tracker ─────────────────────────────────────────────────
-- Movement / Coins / Level Unlocks / each soul group is a named sub-layout;
-- loading one of its files (layouts/parts/<name>_<variant>.json) replaces it.
-- Movement shows only the moves that are shuffled, Level Unlocks only in Open
-- mode, Coins only with Coinsanity, each soul group only when it's played.
-- what tracker.json starts with (Open mode, Movesanity off, no Coinsanity, no souls)
local PART_STATE = { unlocks = "on", movement = "off", coins = "off", souls_npc = "off",
                     souls_toy = "off", souls_enemy = "off", souls_lock = "off",
                     souls_miniboss = "off", souls_boss = "off" }
local function part(name, variant)
  if type(variant) == "boolean" then variant = variant and "on" or "off" end
  if PART_STATE[name] == variant then return end
  PART_STATE[name] = variant
  local file = "layouts/parts/" .. name .. "_" .. variant .. ".json"
  local ok = Tracker:AddLayouts(file)
  print("[TS2] layout " .. file .. (ok == false and " FAILED to load" or ""))
end
local MOVE_VARIANT = { [0] = "off", [1] = "full", [2] = "weapons", [3] = "traversal" }
function ts2_sync_layouts()
  local ok, err = pcall(function()
    part("unlocks", not on("set_mode_1"))
    part("coins", on("set_coinsanity_1"))
    local mv = Tracker:FindObjectForCode("set_movesanity")
    part("movement", MOVE_VARIANT[(mv and mv.CurrentStage) or 0] or "full")
    for _, g in ipairs({ "npc", "toy", "enemy", "lock", "miniboss", "boss" }) do
      local variant = "on"
      if not souls_group_on(g) then
        -- the Final Showdown can still need some of this group's souls
        -- (Woody / Jessie, or the combined Stinky Pete): show just those
        local sub = {}
        for _, c in ipairs(fs_souls_needed()) do
          if SOUL_GROUP[c] == g then sub[#sub + 1] = c:sub(6) end
        end
        variant = (#sub > 0) and table.concat(sub, "_") or "off"
      end
      part("souls_" .. g, variant)
    end
  end)
  if not ok then print("[TS2] layout sync error: " .. tostring(err)) end
end
if ScriptHost and ScriptHost.AddWatchForCode then
  for _, c in ipairs({ "set_mode_1", "set_coinsanity_1", "set_movesanity", "set_movesanity_1",
                      "set_movesanity_2", "set_movesanity_3", "set_souls_npc", "set_souls_toy",
                      "set_souls_enemy", "set_souls_lock", "set_souls_miniboss", "set_souls_boss",
                      "set_souls_fs", "set_souls_wj_woody", "set_souls_wj_jessie" }) do
    ScriptHost:AddWatchForCode("ts2_layout_" .. c, c, function() ts2_sync_layouts() end)
  end
end
